<script setup>
import {formatDateTime} from "../dateTime.js";
import KnowledgeEvidence from "./KnowledgeEvidence.vue";
import {computed,ref,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {api} from '../api.js';import {currentUser,getToken} from '../auth.js';
import {refreshSessionIdentity} from '../sessionIdentity.js';import {useLiveRefresh} from '../useLiveRefresh.js';
import {knowledgeScope,createKnowledgeRequestGate} from '../knowledgeBaseAccess.js';
import {collectionCapabilities,submissionStates,stableOperation} from '../knowledgeCollection.js';
import KnowledgeCardContent from './KnowledgeCardContent.vue';import HelpHint from './HelpHint.vue';
const props=defineProps({review:Boolean});const caps=computed(()=>collectionCapabilities(currentUser.value?.permissions)),identity=computed(()=>knowledgeScope(currentUser.value,getToken()));
const rows=ref([]),total=ref(0),offset=ref(0),status=ref(props.review?'pending':''),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),selected=ref(new Set()),decision=ref(null),note=ref(''),dialog=ref(null),intent=ref(null);
const gate=createKnowledgeRequestGate(),action=createKnowledgeRequestGate();let disposed=false;
const allowed=computed(()=>props.review?caps.value.review:caps.value.view||currentUser.value?.permissions?.includes('kb:submit'));
function clear(){gate.invalidate();action.invalidate();rows.value=[];total.value=0;selected.value=new Set();decision.value=null;note.value='';loading.value=false;busy.value=false;error.value='';notice.value='';}
watch(identity,()=>{clear();if(allowed.value)load();},{flush:'sync'});
function fail(e){if([401,403].includes(e.status)){clear();refreshSessionIdentity().catch(()=>{});}error.value=e.message;}
async function load(background=false){if(!allowed.value||disposed||background&&(busy.value||loading.value||decision.value))return;const ticket=gate.start(identity.value);if(!background){loading.value=true;error.value='';}try{const d=await api.knowledgeSubmissions({review:props.review,status:status.value,limit:20,offset:offset.value});if(!disposed&&gate.accepts(ticket,identity.value)){rows.value=d.submissions||[];total.value=d.total||0;selected.value=new Set([...selected.value].filter(id=>rows.value.some(x=>x.id===id&&x.status==='pending')));error.value='';}}catch(e){if(!disposed&&gate.accepts(ticket,identity.value))fail(e);}finally{if(!disposed&&gate.accepts(ticket,identity.value))loading.value=false;}}
function toggle(id,value){const ids=new Set(selected.value);if(value)ids.add(id);else ids.delete(id);selected.value=ids;}
function preview(items,value){if(!caps.value.review||busy.value||!items.length)return;decision.value={items:JSON.parse(JSON.stringify(items)),value};note.value='';intent.value=null;error.value='';}
async function decide(){if(!decision.value||busy.value||!caps.value.review||decision.value.value==='rejected'&&!note.value.trim())return;const payload={ids:decision.value.items.map(i=>i.id),decision:decision.value.value,note:note.value.trim()},key=stableOperation(intent,'decide',payload),ticket=action.start(identity.value);busy.value=true;error.value='';try{await refreshSessionIdentity();if(disposed||!action.accepts(ticket,identity.value)||!caps.value.review)return;const d=await api.decideKnowledgeCards({...payload,key});if(!disposed&&action.accepts(ticket,identity.value)){if(d.submissions?.length!==payload.ids.length)throw new Error('审核结果未确认，请重试核对。');decision.value=null;selected.value=new Set();notice.value=`已处理 ${d.submissions.length} 张知识卡`;await load();}}catch(e){if(!disposed&&action.accepts(ticket,identity.value))fail(e);}finally{if(!disposed&&action.accepts(ticket,identity.value))busy.value=false;}}
watch(decision,async()=>{await nextTick();if(!disposed&&decision.value&&!dialog.value?.open)dialog.value?.showModal();});
useLiveRefresh(async()=>{if(busy.value||!allowed.value)return;await refreshSessionIdentity().catch(()=>{});if(allowed.value&&!decision.value)await load(true);});onMounted(()=>load());onBeforeUnmount(()=>{disposed=true;clear();});
</script>
<template><section v-if="allowed" class="panel knowledge-submissions"><div class="ui-help-heading"><h2>{{review?'待我审核的知识卡':'我的共享申请'}}</h2><HelpHint label="知识卡共享审核说明">每张卡一次审核，仅通过或驳回。通过后进入共享库，由各位老师自主勾选采用。驳回不影响本人原稿，修改后可重新提交；自己的申请不进入本人审核队列。</HelpHint></div><div class="collection-toolbar"><select v-model="status" aria-label="知识卡申请状态" @change="offset=0;load()"><option value="">全部状态</option><option v-for="(label,key) in submissionStates" :key="key" :value="key">{{label}}</option></select><button class="ghost-button" :disabled="loading" @click="load()">刷新</button><template v-if="review"><button class="primary-button" :disabled="busy||!selected.size" @click="preview(rows.filter(i=>selected.has(i.id)),'approved')">通过所选（{{selected.size}}）</button><button class="ghost-button" :disabled="busy||!selected.size" @click="preview(rows.filter(i=>selected.has(i.id)),'rejected')">驳回所选</button></template></div><p v-if="error" class="collection-error" role="alert">{{error}}</p><p v-if="notice" class="collection-success" role="status">{{notice}}</p><p v-if="loading">加载中…</p><p v-else-if="!rows.length" class="collection-empty">暂无知识卡申请</p><article v-for="item in rows" :key="item.id" class="knowledge-submission"><div class="collection-heading"><label v-if="review&&item.status==='pending'" class="collection-check"><input type="checkbox" :aria-label="`选择审核 ${item.card.title}`" :checked="selected.has(item.id)" @change="toggle(item.id,$event.target.checked)"/>{{item.card.title}}</label><strong v-else>{{item.card.title}}</strong><span>{{submissionStates[item.status]}}<template v-if="item.shared_revision"> · 共享 v{{item.shared_revision}}</template></span></div><p class="collection-meta">{{item.submitter_name}} · 来源私人版本 v{{item.private_revision}} · {{formatDateTime(item.created_at)}}</p><details><summary>查看提交的固定内容</summary><KnowledgeCardContent :card="item.card"/><KnowledgeEvidence :source="item"/></details><p v-if="item.review_note" class="collection-review-note">审核意见：{{item.review_note}}</p><div v-if="review&&item.status==='pending'" class="collection-actions"><button class="primary-button" :disabled="busy" @click="preview([item],'approved')">通过</button><button class="ghost-button" :disabled="busy" @click="preview([item],'rejected')">驳回</button></div><RouterLink v-if="item.shared_card_id&&currentUser?.permissions?.includes('kb:view')" to="/knowledge-base">查看共享知识库</RouterLink></article><div class="collection-actions collection-pager"><span>共 {{total}} 张</span><button class="ghost-button" :disabled="!offset||loading" @click="offset=Math.max(0,offset-20);load()">上一页</button><button class="ghost-button" :disabled="offset+20>=total||loading" @click="offset+=20;load()">下一页</button></div><Teleport to="body"><dialog v-if="decision&&caps.review" ref="dialog" class="collection-dialog" @cancel.prevent="!busy&&(decision=null)"><h2>{{decision.value==='approved'?'通过':'驳回'}}知识卡（{{decision.items.length}}）</h2><p v-if="decision.value==='approved'">确认后发布以下固定内容，拥有共享查看权限的老师均可见，个人原稿保持独立。</p><article v-for="item in decision.items" :key="item.id"><h3>{{item.card.title}}</h3><KnowledgeCardContent :card="item.card"/><KnowledgeEvidence :source="item"/></article><label>审核意见{{decision.value==='rejected'?'（必填）':'（选填）'}}<textarea v-model="note" aria-label="知识卡审核意见" rows="3" maxlength="2000" :disabled="busy"/></label><p v-if="error" class="collection-error" role="alert">{{error}}</p><div class="collection-actions"><button class="ghost-button" :disabled="busy" @click="decision=null">取消</button><button class="primary-button" :disabled="busy||decision.value==='rejected'&&!note.trim()" @click="decide">确认{{decision.value==='approved'?'通过':'驳回'}}</button></div></dialog></Teleport></section><section v-else class="panel">当前身份没有查看此知识卡队列的权限。</section></template>
